<?php
// Isolated SQLite and fake PC telemetry. No network, artwork download or printer access.
require __DIR__.'/../vendor/autoload.php';
$app=require __DIR__.'/../bootstrap/app.php';$app->make(Illuminate\Contracts\Console\Kernel::class)->bootstrap();
set_exception_handler(function(Throwable $e):void{fwrite(STDERR,'FAIL: '.$e.PHP_EOL);exit(1);});
config(['database.default'=>'sqlite','database.connections.sqlite.database'=>':memory:','session.driver'=>'array']);Illuminate\Support\Facades\DB::purge('sqlite');
foreach(glob(__DIR__.'/../database/migrations/*.php') as $file)(require $file)->up();
use App\Models\{FactoryAgent,PrintBatch,User,ProductionItem};
use App\Services\{FactoryDispatchService,ProductionService,ArtworkMatcherService};
use Illuminate\Http\Request;
use Illuminate\Support\Facades\DB;
$checks=0;$check=function($ok,$label)use(&$checks){if(!$ok)throw new RuntimeException($label);echo 'PASS: '.$label.PHP_EOL;$checks++;};
$reject=function($fn,$status)use($check){try{$fn();throw new LogicException('Unsafe action accepted');}catch(Symfony\Component\HttpKernel\Exception\HttpException $e){$check($e->getStatusCode()===$status,'Unsafe transition rejected with HTTP '.$status);}};
$dispatch=app(FactoryDispatchService::class);$factory=new App\Http\Controllers\FactoryController();
$user=User::create(['name'=>'Admin','email'=>'dispatch@example.test','role'=>'admin','password'=>'unused']);
$id='ea1ec5ee-6313-431d-9f60-8c7834a601be';
$agent=FactoryAgent::create(['agent_id'=>$id,'sampled_at_ms'=>now()->getTimestampMs(),'last_seen_at'=>now(),'telemetry'=>['reporter_mode'=>'connection_only','process_status'=>'running','stage'=>'idle'],'activity'=>[]]);
$check(!$agent->fresh()->processing_enabled && $dispatch->next($id)===null,'New installations cannot process jobs until an administrator enables a real listener');
$reject(fn()=>$dispatch->configure($agent,true,$user->id),422);
$check($dispatch->readiness()['state']==='connection_only','Connection-only reporter is explicitly identified as unable to process queue');
$agent->update(['telemetry'=>['reporter_mode'=>'listener','process_status'=>'running','stage'=>'idle']]);
$dispatch->configure($agent,true,$user->id);
$check($agent->fresh()->processing_enabled && count($agent->fresh()->control_audit)===1,'Administrator enable is audited');
$svc=new ProductionService();
$make=function($line)use($svc,$user){$item=ProductionItem::create(['line_item_id'=>$line,'product'=>'Selected artwork','variant'=>'PSE','quantity'=>1,'series_code'=>'PSE','design_type'=>'single','match_status'=>'REVIEW','artwork_review'=>['policy'=>ArtworkMatcherService::POLICY],'matches'=>[['id'=>'drive-'.$line,'side'=>'single','name'=>'PSE-TEST.jpg']]]);$svc->verify($item,'CORRECT',$user->id);return $item;};
$a=$make('dispatch-a');$b=$make('dispatch-b');$batch=$svc->batch($user->id,[$a->id]);
$check($batch->order_count===1 && $batch->payload['orders'][0]['line_item_id']===$a->line_item_id && $svc->queue()->contains('id',$b->id),'Single-item pilot queues only the selected approved product');
$snapshot=$batch->payload;DB::transaction(fn()=>$dispatch->request($batch));$batch->refresh();
$check($factory->next()->getData(true)['batch']===null,'Legacy worker cannot claim a portal-managed batch');
$request=fn($input=[])=>Request::create('/api/factory/work','POST',$input,[],[],['HTTP_X_FACTORY_AGENT_ID'=>$id]);
$check($dispatch->next($id)===['id'=>$batch->id,'phase'=>'prepare'],'Enabled listener sees authorized preparation only');
$op=$dispatch->begin($request(),$batch,'prepare');$batch->refresh();
$check($batch->status==='CLAIMED' && !array_key_exists('agent_operation_token',$batch->toArray()),'Atomic begin binds a private phase token and claims the batch');
$reject(fn()=>$dispatch->begin($request(),$batch,'prepare'),409);
$check($dispatch->next($id)===null,'An active phase blocks launching another worker');
$bad=$request(['status'=>'DOWNLOADING']);$reject(fn()=>$factory->status($bad,$batch),409);
$owned=function($input=[])use($request,$op){$r=$request($input);$r->headers->set('X-Factory-Operation',$op['token']);return $r;};
$assigned=$factory->assigned($owned(),$batch,$dispatch)->getData(true)['batch'];$check($assigned['id']===$batch->id,'Only the bound worker can fetch the assigned phase');
$factory->status($owned(['status'=>'DOWNLOADING']),$batch);$batch->refresh();
$reject(fn()=>$factory->assigned($owned(),$batch,$dispatch),409);
$agent->refresh()->update(['telemetry'=>['reporter_mode'=>'managed_worker','process_status'=>'running','batch_id'=>$batch->id,'stage'=>'downloading','progress'=>['completed'=>0,'total'=>1,'phase'=>'downloading','bytes_done'=>10,'bytes_total'=>100]]]);
$check($dispatch->progress($batch)['progress']['bytes_done']===10,'Progress shows current worker evidence rather than a fabricated timer');
$agent->update(['last_seen_at'=>now()->subMinutes(3)]);$check($dispatch->progress($batch)['progress']===null && $dispatch->progress($batch)['worker_state']==='offline','Expired worker evidence hides the progress bar and reports offline');
$agent->update(['last_seen_at'=>now()]);$factory->status($owned(['status'=>'PREPARED']),$batch);$batch->refresh();
$check($dispatch->progress($batch)['can_handoff'] && !$dispatch->progress($batch)['can_confirm_printed'],'Preparation requires signed handoff, never confirms printing');
$batch->update(['status'=>'HANDOFF_REQUESTED']);$reject(fn()=>$dispatch->begin($request(),$batch,'handoff'),422);
$batch->confirmations()->create(['action'=>'HANDOFF','user_id'=>$user->id,'account_name'=>'Admin','signer_name'=>'Test operator','confirmed_at'=>now(),'order_count'=>1,'artwork_file_count'=>1,'total_sets'=>1,'payload_sha256'=>hash('sha256',json_encode($snapshot))]);
$handoff=$dispatch->begin($request(),$batch,'handoff');$batch->refresh();
$reject(fn()=>$factory->status($owned(['status'=>'DELIVERING']),$batch),409);
$r=$request(['status'=>'DELIVERING']);$r->headers->set('X-Factory-Operation',$handoff['token']);$factory->status($r,$batch);$batch->refresh();
$reject(fn()=>$factory->assigned($r,$batch,$dispatch),409);
$reject(fn()=>$dispatch->begin($request(),$batch,'handoff'),409);
$r->request->set('status','SENT_TO_RIP');$factory->status($r,$batch);$batch->refresh();
$check($batch->status==='SENT_TO_RIP' && $batch->payload===$snapshot && !$batch->completed_at && $dispatch->progress($batch)['can_confirm_printed'],'Delivery preserves immutable artwork and awaits physical print confirmation');
$dispatch->configure($agent,false,$user->id);$check($dispatch->next($id)===null,'Pause prevents starting another phase');
$normal=new User(['role'=>'operator']);$r=Request::create('/admin/control','POST',['enabled'=>true,'confirm_control'=>true]);$r->setUserResolver(fn()=>$normal);$monitor=new App\Http\Controllers\FactoryMonitoringController();
$reject(fn()=>$monitor->processing($r,$agent,$dispatch),403);
$reject(fn()=>$monitor->portalPackage($r),403);$reject(fn()=>$monitor->portalSetup($r),403);
$check(!str_contains(json_encode($dispatch->progress($batch)),$handoff['token']),'Public batch progress never exposes worker operation tokens');
$blocked=PrintBatch::create(['batch_id'=>'BLOCKED-PROGRESS','status'=>'QUEUED','order_count'=>1,'artwork_file_count'=>1,'payload'=>[],'automation_requested_at'=>now(),'factory_agent_id'=>$id]);
$agent->refresh()->update(['last_seen_at'=>now(),'telemetry'=>['reporter_mode'=>'listener','process_status'=>'running','stage'=>'error','batch_id'=>$blocked->id,'last_failure'=>['error_code'=>'manual_inspection_required']]]);
$check($dispatch->progress($blocked)['severity']==='danger' && str_contains($dispatch->progress($blocked)['title'],'restart blocked'),'A locally blocked uncertain attempt is visible on the batch page instead of silently waiting forever');
echo "$checks factory dispatch checks passed.\n";
